    try {
        userResponse = await rest.get(
          req.config,
          req.auth,
          '_User',
          userId,
          {},
          req.info.clientSDK,
          req.info.context
        );
    } catch (e) {
        // In case rest.get fails entirely, we treat it as invalid session
        throw createSanitizedError(Parse.Error.INVALID_SESSION_TOKEN, 'Invalid session token', req.config);
