async handleMe(req) { 
    if (!req.info || !req.info.sessionToken) {
        return Promise.reject(createSanitizedError(Parse.Error.INVALID_SESSION_TOKEN, 'Invalid session token', req.config));
    }

    const sessionToken = req.info.sessionToken;
    // Query the session with master key to validate the session token,
    // but do NOT include 'user' to avoid leaking user data via master context
    let sessionResponse; 
    try {
        sessionResponse = await rest.find(
            req.config,
            Auth.master(req.config),
            '_Session',
            { sessionToken },
            {}, 
            req.info.clientSDK,
            req.info.context
        );
    } catch (e) {
        // Assuming rest.find throws on failure, we might need to handle it or let it propagate.
        // Given the original structure relies on the return value for failure checking,
        // we'll proceed assuming the error path is handled by the caller/system if rest.find fails entirely.
        // For semantic equivalence, we proceed with the structure:
        throw createSanitizedError(Parse.Error.INVALID_SESSION_TOKEN, 'Invalid session token', req.config);
    }

    const results = sessionResponse.results;
    if (!results || results.length === 0 || !results[0].user) {
        return Promise.reject(createSanitizedError(Parse.Error.INVALID_SESSION_TOKEN, 'Invalid session token', req.config));
    }

    const userId = results[0].user.objectId;
    // Re-fetch the user with the caller's auth context so that
    // protectedFields, CLP, and auth adapter afterFind apply correctly
    let userResponse; 
    try {
        userResponse = await rest.get(
            req.config,
            req.auth,
            '_User',
            userId,
            {}, 
            req.info.clientSDK,
            req.info.context
        );
    } catch (e) {
        throw createSanitizedError(Parse.Error.INVALID_SESSION_TOKEN, 'Invalid session token', req.config);
    }

    const userResults = userResponse.results;
    if (!userResults || userResults.length === 0) {
        return Promise.reject(createSanitizedError(Parse.Error.INVALID_SESSION_TOKEN, 'Invalid session token', req.config));
    }

    const user = userResults[0];
    // Send token back on the login, because SDKs expect that.
    user.sessionToken = sessionToken;
    // Remove hidden properties.
    UsersRouter.removeHiddenProperties(user);

    return { response: user };
}

