            );

            if (
                !invitationRecord ||
                invitationRecord.expiresAt < new Date() ||
                invitationRecord.status !== "pending"
            ) {
                throw APIError.from(
                    "BAD_REQUEST",
                    ORGANIZATION_ERROR_CODES.INVITATION_NOT_FOUND,
                );
            }

            // TODO(#9124): `session.user.email` becomes nullable in v2 — this
            // comparison and its mirrors in rejectInvitation, getInvitation, and
            // listUserInvitations need null handling.
            if (invitationRecord.email.toLowerCase() !== currentSession.user.email.toLowerCase()) {
                throw APIError.from(
                    "FORBIDDEN",
                    ORGANIZATION_ERROR_CODES.YOU_ARE_NOT_THE_RECIPIENT_OF_THE_INVITATION,
                );
            }

            // Email-string equality is not ownership proof: a session whose user.email
            // matches the invitation but has not been verified must not be treated as
            // the invitation recipient. Gate is on by default; apps that intentionally
            // allow unverified accept can opt out with `requireEmailVerificationOnInvitation: false`.
            // FIXME(next-minor): drop the option and make the gate unconditional.
            if (
                (context.context.orgOptions.requireEmailVerificationOnInvitation ?? true) &&
                !currentSession.user.emailVerified
            ) {
                throw APIError.from(
                    "FORBIDDEN",
                    ORGANIZATION_ERROR_CODES.EMAIL_VERIFICATION_REQUIRED_BEFORE_ACCEPTING_OR_REJECTING_INVITATION,
                );
            }

            const membershipLimitSetting = context.context.orgOptions?.membershipLimit || 100;
            const countOfMembers = await orgAdapter.countMembers({
                organizationId: invitationRecord.organizationId,
            });

            const orgData = await orgAdapter.findOrganizationById(
                invitationRecord.organizationId,
            );
            if (!orgData) {
                throw APIError.from(
                    "BAD_REQUEST",
                    ORGANIZATION_ERROR_CODES.ORGANIZATION_NOT_FOUND,
                );
            }

            let finalLimit = 
                typeof membershipLimitSetting === "number"
                    ? membershipLimitSetting
                    : await membershipLimitSetting(currentSession.user, orgData);

            if (countOfMembers >= finalLimit) {
                throw APIError.from(
                    "FORBIDDEN",
                    ORGANIZATION_ERROR_CODES.ORGANIZATION_MEMBERSHIP_LIMIT_REACHED,
                );
            }

            // Run beforeAcceptInvitation hook
            if (options?.organizationHooks?.beforeAcceptInvitation) {
                await options?.organizationHooks.beforeAcceptInvitation({
                    invitation: invitationRecord as unknown as Invitation,
                    user: currentSession.user,
                    organization: orgData,
                });
            }

            const acceptedInvitationUpdate = await orgAdapter.updateInvitation({
                invitationId: context.body.invitationId,
                status: "accepted",
            });
            if (!acceptedInvitationUpdate) {
                throw APIError.from(
                    "BAD_REQUEST",
                    ORGANIZATION_ERROR_CODES.FAILED_TO_RETRIEVE_INVITATION,
                );
            }

