                        typeof context.context.orgOptions.teams.maximumMembersPerTeam !==
                        "undefined"
                    ) {
                        const currentMembers = await orgAdapter.countTeamMembers({ teamId: tId });

                        const maxMembers = 
                            typeof context.context.orgOptions.teams.maximumMembersPerTeam ===
                            "function"
                                ? await context.context.orgOptions.teams.maximumMembersPerTeam({
                                        teamId: tId,
                                        session: currentSession,
                                        organizationId: invitationRecord.organizationId,
                                    })
                                : context.context.orgOptions.teams.maximumMembersPerTeam;

                        if (currentMembers >= maxMembers) {
                            throw APIError.from(
                                "FORBIDDEN",
                                ORGANIZATION_ERROR_CODES.TEAM_MEMBER_LIMIT_REACHED,
                            );
                        }
                    }
                }

                if (isSingleTeam) {
                    const finalTeamId = teamIdArray[0]!;
                    const updatedSessionData = await orgAdapter.setActiveTeam(
                        currentSession.session.token,
                        finalTeamId,
                        context,
