                organizationId: invitationRecord.organizationId,
                userId: currentSession.user.id,
                role: invitationRecord.role,
                createdAt: new Date(),
            });

            await orgAdapter.setActiveOrganization(
                currentSession.session.token,
                invitationRecord.organizationId,
                context,
            );
            if (options?.organizationHooks?.afterAcceptInvitation) {
                await options?.organizationHooks.afterAcceptInvitation({
                    invitation: acceptedInvitationUpdate as unknown as Invitation,
                    member: newMember,
                    user: currentSession.user,
                    organization: orgData,
                });
            }
            return context.json({
                invitation: acceptedInvitationUpdate,
                member: newMember,
            });
        }

