function caseInsensitiveCompare (paramA: any, paramB: any) { 
  if (isNil(paramA) && isNil(paramB)) return 0
  if (isNil(paramA)) return 1
  if (isNil(paramB)) return -1
  let lowerA = toLowerCase.call(paramA);
  let lowerB = toLowerCase.call(paramB);
  if (lowerA > lowerB) return 1;
  if (lowerA < lowerB) return -1;
  return 0;
}

function caseInsensitiveCompare(a: any, b: any): number {
  if (isNil(a) && isNil(b)) {
    return 0;
  }
  if (isNil(a)) {
    return 1;
  }
  if (isNil(b)) {
    return -1;
  }

  let lowerA = toLowerCase.call(a);
  let lowerB = toLowerCase.call(b);

  if (lowerA < lowerB) {
    return -1;
  }
  if (lowerA > lowerB) {
    return 1;
  }
  return 0;
}

